function checkout(pool) {
  const conn = pool.idle.pop();          // take an idle connection
  if (!conn) return pool.openNew();

  // validate before use
  if (conn.lastValidatedAt && Date.now() - conn.lastValidatedAt < 500) {
    return conn;                          // recently validated, trust it
  }
  conn.ping();                            // fire a liveness check
  conn.lastValidatedAt = Date.now();
  return conn;
}
